// n8n Code node - JavaScript
// Input: item.json.text (contains the labeled Arabic article)

const item = $input.first().json.content.parts[0]
const raw = (item.text ?? "").toString();

// Convert literal "\n" to real newlines
let s = raw.replace(/\r/g, "");
if (s.includes("\\n")) s = s.replace(/\\n/g, "\n");

// Normalize blank lines
s = s.replace(/\n{3,}/g, "\n\n").trim();

// Arabic section labels
const labels = ["التصنيف", "العنوان", "المقدمة", "التفاصيل", "الخاتمة", "الكلمات_المفتاحية"];
const labelPattern = labels.join("|");

// Helper function to capture each section
function capture(label) {
  const re = new RegExp(`${label}\\s*:\\s*([\\s\\S]*?)(?=\\n\\n(?:${labelPattern})\\s*:|$)`, "m");
  const m = s.match(re);
  return m ? m[1].trim() : "";
}

const category   = capture("التصنيف");
const title      = capture("العنوان");
const intro      = capture("المقدمة");
const details    = capture("التفاصيل");
const conclusion = capture("الخاتمة");

// Build body paragraphs
const paragraphs = [intro, details, conclusion]
  .map(p => p && p.replace(/\s+/g, " ").trim())
  .filter(Boolean);

const body = paragraphs.join("\n\n");

// Combine title + body for full readable article
const news_text = [title, body].filter(Boolean).join("\n\n").trim();

let formated_text={
    json: {
      category,
      title,
      body,
      news_text,   // full text for ElevenLabs
      clean_text: body
    }
  }
// Return a single item with cleaned fields
return formated_text;
